import * as THREE from '../vendor/three.module.js';
// Logical box meshes remain available for exact CSG/inspection. Only their
// exposed render surfaces are batched, within ONE owning transport body.
export function syncBodyBatches(view){view.batchMetrics??={rebuiltBodies:0,batches:0};for(const [id,body]of Object.entries(view.groups)){const excluded=new Set([...view.shutters.filter(s=>s.id===id).map(s=>s.group),...(view.adaptivePortals??[]).filter(p=>p.id===id).map(p=>p.group)]),sources=[];body.traverse(m=>{if(!m.isMesh||m.userData.batchProxy||!m.userData.sourceBox)return;for(let p=m;p&&p!==body;p=p.parent)if(excluded.has(p)||p.userData.target)return;sources.push(m);});const signature=sources.map(m=>m.uuid+':'+m.geometry.uuid+':'+!!m.userData.internalSurface).join('|');if(body.userData.batchSignature===signature)continue;body.userData.batchSignature=signature;const old=body.userData.batchGroup;if(old){old.traverse(m=>m.geometry?.dispose());body.remove(old);}const group=new THREE.Group();group.userData.batchOwner=id;body.add(group);body.userData.batchGroup=group;const roofSet=new Set(view.roofs),sets=new Map(),inverse=body.matrixWorld.clone().invert();for(const m of sources){m.userData.batchSource=true;m.visible=false;m.updateMatrix();m.matrixAutoUpdate=false;if(m.userData.internalSurface)continue;const roof=roofSet.has(m),role=m.userData.wallRole??'static-fixture',hasUV=!!m.geometry.attributes.uv,key=m.material.uuid+':'+roof+':'+role+':'+hasUV;let set=sets.get(key);if(!set)sets.set(key,set={mat:m.material,roof,role,positions:[],normals:[],uvs:[],members:[]});const transform=inverse.clone().multiply(m.matrixWorld),normalMatrix=new THREE.Matrix3().getNormalMatrix(transform),g=m.geometry,p=g.attributes.position,n=g.attributes.normal,uv=g.attributes.uv,index=g.index,vertex=new THREE.Vector3(),normal=new THREE.Vector3();set.members.push(m.uuid);for(let i=0;i<(index?.count??p.count);i++){const k=index?index.getX(i):i;vertex.fromBufferAttribute(p,k).applyMatrix4(transform);normal.fromBufferAttribute(n,k).applyMatrix3(normalMatrix).normalize();set.positions.push(vertex.x,vertex.y,vertex.z);set.normals.push(normal.x,normal.y,normal.z);if(hasUV)set.uvs.push(uv.getX(k),uv.getY(k));}}for(const set of sets.values()){const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(set.positions,3));geometry.setAttribute('normal',new THREE.Float32BufferAttribute(set.normals,3));if(set.uvs.length)geometry.setAttribute('uv',new THREE.Float32BufferAttribute(set.uvs,2));geometry.computeBoundingBox();geometry.computeBoundingSphere();const mesh=new THREE.Mesh(geometry,set.mat);Object.assign(mesh.userData,{batchProxy:true,owner:id,wallRole:set.role,batchRoof:set.roof,sourceMembers:set.members});mesh.updateMatrix();mesh.matrixAutoUpdate=false;group.add(mesh);}view.batchMetrics.rebuiltBodies++;}view.batchMetrics.batches=Object.values(view.groups).reduce((n,g)=>n+(g.userData.batchGroup?.children.length??0),0);}
export function showBodyBatches(view,overview){for(const body of Object.values(view.groups))for(const mesh of body.userData.batchGroup?.children??[])mesh.visible=!mesh.userData.batchRoof||!overview;}
